const newItems = [];
const item = items[0];

for (const key of Object.keys(item.binary)) {
  const file = item.binary[key];
  const isPdf = file.mimeType === 'application/pdf';

  if (isPdf) {
    newItems.push({
      json: item.json,
      binary: {
        data: file
      }
    });
  }
}

return newItems;
